#ifndef OPTIONS_DEFS_H
#define OPTIONS_DEFS_H 1

#define BINOMIAL_NUM 64

#endif // OPTIONS_DEFS_H

#include <algorithm>
#include <math.h>

// Cumulative normal distribution function
static inline float CND(float X) {
    float L = fabsf(X);

    float k = 1.f / (1.f + 0.2316419f * L);
    float k2 = k * k;
    float k3 = k2 * k;
    float k4 = k2 * k2;
    float k5 = k3 * k2;

    const float invSqrt2Pi = 0.39894228040f;
    float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
    w *= invSqrt2Pi * expf(-L * L * .5f);

    if (X > 0.f)
        w = 1.f - w;
    return w;
}

void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
    for (int i = 0; i < count; ++i) {
        float S = Sa[i], X = Xa[i];
        float T = Ta[i], r = ra[i];
        float v = va[i];

        float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
        float d2 = d1 - v * sqrtf(T);

        result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
    }
}

void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
    float V[BINOMIAL_NUM];
    double q_powers[BINOMIAL_NUM];

    for (int i = 0; i < count; ++i) {
        float S = Sa[i], X = Xa[i];
        float T = Ta[i], r = ra[i];
        float v = va[i];

        float dt = T / BINOMIAL_NUM;
        float u = expf(v * sqrtf(dt));
        float d = 1.f / u;
        float disc = expf(r * dt);
        float Pu = (disc - d) / (u - d);

        for (int j = 0; j < BINOMIAL_NUM; ++j) {
            float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
            V[j] = std::max(0.f, X - S * upow);
        }

        // The 64 terminal values are indexed 0..63, with exponents 2*j-64.
        // The backward loop has 63 effective updates, so its weights are
        // C(63,j) * Pu^j * (1-Pu)^(63-j), followed by 63 discount divisions.
        double q = (double)(1.f - Pu);
        q_powers[0] = 1.0;
        for (int j = 1; j < BINOMIAL_NUM; ++j)
            q_powers[j] = q_powers[j - 1] * q;

        double p = (double)Pu;
        double p_power = 1.0;
        double binomial_coefficient = 1.0;
        double weighted_payoff = 0.0;
        for (int j = 0; j < BINOMIAL_NUM; ++j) {
            double weight = binomial_coefficient * p_power * q_powers[BINOMIAL_NUM - 1 - j];
            weighted_payoff += weight * (double)V[j];

            if (j + 1 < BINOMIAL_NUM) {
                binomial_coefficient *= (double)(BINOMIAL_NUM - 1 - j) / (double)(j + 1);
                p_power *= p;
            }
        }

        double inverse_discount = 1.0 / (double)disc;
        double discount_factor = 1.0;
        for (int step = 0; step < BINOMIAL_NUM - 1; ++step)
            discount_factor *= inverse_discount;

        result[i] = (float)(weighted_payoff * discount_factor);
    }
}
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>
extern "C" void run(const void* input1,const void* input2,void* output,int n,int parameter,int threads)
{float*a=(float*)input1;binomial_put_serial(a,a+n,a+2*n,a+3*n,a+4*n,(float*)output,n);}
